function sortDiscoveredSkills(list: AIAgentSkillDefinition[]): AIAgentSkillDefinition[] {
  const PREFERRED = [
    'procedural-modeler',
    'voxel-painter',
    'mesh-updater',
    'image-to-mesh',
  ];
  return list.sort((a, b) => {
    const idxA = PREFERRED.indexOf(a.id);
    const idxB = PREFERRED.indexOf(b.id);
    if (idxA !== -1 && idxB !== -1) return idxA - idxB;
    if (idxA !== -1) return -1;
    if (idxB !== -1) return 1;
    return a.id.localeCompare(b.id);
  });
}

/**
 * Dynamically discovers skills from Webpack require.context (if in Webpack environment)
 * or Node.js filesystem (if in Node/Electron environment), falling back to precompiled skills.
 */
export function discoverSkills(): AIAgentSkillDefinition[] {
  // 1. Try Webpack require.context if available
  try {
    const context = require.context('../skills', true, /\.md$/);
    const discovered: AIAgentSkillDefinition[] = [];
    context.keys().forEach((key: string) => {
      if (/readme/i.test(key)) return;
      const rawContent = context(key);
      const text = typeof rawContent === 'string' ? rawContent : rawContent?.default || '';
      const baseName = key.replace(/^\.\//, '').replace(/\.md$/, '').split('/').pop() || 'skill';
      const fallbackId = baseName.toUpperCase() === 'SKILL' ? key.split('/')[1] : baseName;
      discovered.push(parseSkillMarkdown(text, fallbackId));
    });
    if (discovered.length > 0) {
      return sortDiscoveredSkills(discovered);
    }
  } catch {
    // Ignore and proceed to fallback
  }

  // 2. Try Node.js filesystem if available (Electron / tests / local runtime)
  try {
    const hasProcess = typeof globalThis !== 'undefined' && Boolean((globalThis as any).process?.versions?.node);
    if (hasProcess) {
      const dynamicRequire = eval('require');
      const nodeFs = dynamicRequire('fs');
      const nodePath = dynamicRequire('path');
      if (nodeFs && nodePath) {
        const candidateDirs = [
          nodePath.resolve(process.cwd(), 'skills'),
          nodePath.resolve(__dirname, '../skills'),
        ];
        for (const dir of candidateDirs) {
          if (nodeFs.existsSync(dir)) {
            const list = nodeFs.readdirSync(dir);
            const found: AIAgentSkillDefinition[] = [];
            for (const file of list) {
              if (file.endsWith('.md') && !file.toLowerCase().startsWith('readme')) {
                const fullPath = nodePath.join(dir, file);
                const content = nodeFs.readFileSync(fullPath, 'utf8');
                const baseName = nodePath.basename(file, '.md');
                found.push(parseSkillMarkdown(content, baseName));
              }
            }
            if (found.length > 0) {
              return sortDiscoveredSkills(found);
            }
          }
        }
      }
    }
  } catch {
    // Ignore and proceed to fallback
  }

  // 3. Return precompiled skills list
  return sortDiscoveredSkills(BUILT_IN_AGENT_SKILLS.map((s) => ({ ...s })));
}
